from abc import ABC, abstractmethod
from typing import List, Optional

from src.sidecar import AbstractSidecarStore, get_writer
from .result import ProcessingResult


class ResultSaver(ABC):
    """Abstract sink for processing results."""

    @abstractmethod
    def save(self, result: ProcessingResult) -> None:
        """Persist (or collect) one ProcessingResult."""
        ...


class SidecarResultSaver(ResultSaver):
    """Write each result as a sidecar JSON file next to the source image."""

    def __init__(self, store: Optional[AbstractSidecarStore] = None):
        """Initialise with the given sidecar store (defaults to singleton)."""
        self._writer = store or get_writer()

    def save(self, result: ProcessingResult) -> None:
        data = result.as_dict()
        if result.image_path:
            self._writer.save(result.image_path, data)


class CollectingSidecarSaver(SidecarResultSaver):
    """Like SidecarResultSaver but also accumulates results in a list."""

    def __init__(self, store: Optional[AbstractSidecarStore] = None):
        super().__init__(store=store)
        self.results: List[dict] = []

    def save(self, result: ProcessingResult) -> None:
        super().save(result)
        self.results.append(result.as_dict())


class InMemoryCollector(ResultSaver):
    """Accumulate ProcessingResult objects in memory (no sidecar write)."""

    def __init__(self):
        self.results: List[ProcessingResult] = []

    def save(self, result: ProcessingResult) -> None:
        self.results.append(result)


class NoOpResultSaver(ResultSaver):
    """Discards all results (useful for testing or dry-runs)."""

    def save(self, result: ProcessingResult) -> None:
        pass

from abc import ABC, abstractmethod
from typing import List, Optional

from src.discovery import PhotoList


class ImageSource(ABC):
    """Abstract source of image paths for batch processing."""

    @abstractmethod
    def list_images(self, limit: Optional[int] = None) -> List[str]:
        """Return a list of absolute image file paths, optionally capped by limit."""
        ...

    @abstractmethod
    def total_pending(self) -> int:
        """Return the total count of images awaiting processing."""
        ...


class FolderImageSource(ImageSource):
    """Image source that discovers photos from a directory on disk."""

    def __init__(self, folder: str, recursive: bool = True, exclude_processed: bool = True):
        """Initialise the folder-based image source.

        Args:
            folder: Absolute path to the directory to scan.
            recursive: If True, scan sub-directories.
            exclude_processed: If True, skip images already marked as completed
                in the database tracker or sidecar data.
        """
        self.folder = folder
        self.recursive = recursive
        self.exclude_processed = exclude_processed
        self._discovery = PhotoList(recursive=recursive)
        # Cache only the full list of all images (doesn't change during processing)
        # Pending list is NOT cached as it changes when images are processed
        self._cached_all: Optional[List[str]] = None

    def _get_all(self) -> List[str]:
        """Return all image paths in the folder (cached after first call)."""
        if self._cached_all is None:
            self._cached_all = self._discovery.list_photos([self.folder])
        return self._cached_all

    def _get_pending(self) -> List[str]:
        """Return only unprocessed image paths.

        Note: This is NOT cached because the pending set changes as images
        are processed. Each call recomputes from the current state.
        """
        if self.exclude_processed:
            return self._discovery.list_photos(
                [self.folder], exclude_processed_from=self.folder
            )
        else:
            return self._get_all()

    def list_images(self, limit: Optional[int] = None) -> List[str]:
        """Return pending image paths, optionally capped by limit."""
        images = self._get_pending()
        if limit is not None:
            return images[:limit]
        return images

    def total_pending(self) -> int:
        """Return the number of pending (unprocessed) images."""
        return len(self._get_pending())

    def total_all(self) -> int:
        """Return the total number of images regardless of processed status."""
        return len(self._get_all())


class ExplicitPathSource(ImageSource):
    """Image source backed by an explicit list of paths (not a folder scan)."""

    def __init__(self, paths: List[str]):
        self._paths = paths

    def list_images(self, limit: Optional[int] = None) -> List[str]:
        """Return the explicit paths list, optionally capped by limit."""
        result = self._paths
        if limit is not None:
            result = result[:limit]
        return result

    def total_pending(self) -> int:
        """Return the number of explicit paths."""
        return len(self._paths)

import logging
from abc import ABC, abstractmethod
from typing import Optional

from src.batch_state import write_batch_state
from .result import ProcessingResult, BatchStats

logger = logging.getLogger(__name__)


class ProgressReporter(ABC):
    """Abstract hook for reporting batch processing progress."""

    @abstractmethod
    def report_start(self, total: int) -> None:
        """Called when processing begins, with the total image count."""
        ...

    @abstractmethod
    def report_progress(self, current: int, current_result: ProcessingResult) -> None:
        """Called after each image is processed, with 1-based index and result."""
        ...

    @abstractmethod
    def report_done(self, stats: BatchStats) -> None:
        """Called when the batch is complete, with aggregate stats."""
        ...


class FileProgressReporter(ProgressReporter):
    """Writes batch state to ``.open-photo-agent/batch_state.json`` on each event."""

    def __init__(self, folder: str):
        self.folder = folder
        self._total = 0
        self._embedding_health_failures = 0

    def report_start(self, total: int) -> None:
        self._total = total
        write_batch_state(self.folder, "running", total, 0)

    def report_progress(self, current: int, current_result: ProcessingResult) -> None:
        # Track embedding health failures
        extra = {}
        if current_result.embedding_error and "health check failed" in current_result.embedding_error.lower():
            self._embedding_health_failures += 1
            extra["embedding_health_failures"] = self._embedding_health_failures
        write_batch_state(self.folder, "running", self._total, current, **extra)

    def report_done(self, stats: BatchStats) -> None:
        extra = {"embedding_health_failures": self._embedding_health_failures}
        write_batch_state(
            self.folder, "done", stats.total, stats.success_count + stats.failure_count,
            min_duration_ms=stats.min_duration_ms,
            max_duration_ms=stats.max_duration_ms,
            avg_duration_ms=stats.avg_duration_ms,
            total_model_time_s=stats.total_duration_ms / 1000,
            **extra,
        )


class ConsoleProgressReporter(ProgressReporter):
    """Minimal reporter that logs the start count only."""

    def report_start(self, total: int) -> None:
        logger.info("Processing %d image(s)", total)

    def report_progress(self, current: int, current_result: ProcessingResult) -> None:
        pass

    def report_done(self, stats: BatchStats) -> None:
        pass


class BatchProgressReporter(ProgressReporter):
    """Reports per-image progress for a sub-batch that is part of a larger job.

    Writes ``status="running_all"`` with the *global* total so the UI
    progress bar advances smoothly across the entire run.

    When ``batch_total`` is provided, additional keys (``batch_num``,
    ``batch_total``, ``batch_size``, ``batch_offset``) are written so the
    UI can render a secondary "current batch" progress bar.

    Also tracks embedding health check failures and includes them in the batch state.
    """

    def __init__(
        self,
        folder: str,
        total: int,
        offset: int = 0,
        batch_num: int = 1,
        batch_total: Optional[int] = None,
        batch_size: Optional[int] = None,
    ):
        self.folder = folder
        self._total = total
        self._offset = offset
        self._batch_num = batch_num
        self._batch_total = batch_total
        self._batch_size = batch_size
        self._embedding_health_failures = 0

    def report_start(self, total: int) -> None:
        pass

    def report_progress(self, current: int, current_result: ProcessingResult) -> None:
        extra: dict = {"batch_offset": self._offset}
        if self._batch_total is not None:
            extra["batch_num"] = self._batch_num
            extra["batch_total"] = self._batch_total
        if self._batch_size is not None:
            extra["batch_size"] = self._batch_size

        # Track embedding health failures
        if current_result.embedding_error and "health check failed" in current_result.embedding_error.lower():
            self._embedding_health_failures += 1
            extra["embedding_health_failures"] = self._embedding_health_failures

        write_batch_state(
            self.folder, "running_all", self._total, self._offset + current, **extra
        )

    def report_done(self, stats: BatchStats) -> None:
        pass


class NoOpProgressReporter(ProgressReporter):
    """Silent reporter that produces no output (default when none specified)."""

    def report_start(self, total: int) -> None:
        pass

    def report_progress(self, current: int, current_result: ProcessingResult) -> None:
        pass

    def report_done(self, stats: BatchStats) -> None:
        pass

from typing import Callable, Dict, Optional

from src.interfaces import BasePhotoExtractor


class ExtractorProvider:
    """Lazy singleton-style provider that caches extractor instances by params."""

    def __init__(self, backend_factory: Callable[..., BasePhotoExtractor]):
        self._factory = backend_factory
        self._current: Optional[BasePhotoExtractor] = None
        self._current_params: Dict = {}

    def get(self, host: str, port: int, model: str, timeout: int, backend: str) -> BasePhotoExtractor:
        """Return (or create) an extractor matching the given parameters.

        If the parameters match the currently cached instance, it is reused.
        Otherwise a new extractor is created via the factory.
        """
        params = {"host": host, "port": port, "model": model, "timeout": timeout, "backend": backend}
        if self._current and self._current_params == params:
            return self._current
        self._current = self._factory(backend=backend, host=host, port=port, model=model, timeout=timeout)
        self._current_params = params
        return self._current

    def health_check(self) -> bool:
        """Check health of the cached extractor. Returns False if not created yet."""
        if self._current is None:
            return False
        return self._current.health_check()

    def invalidate(self) -> None:
        """Clear the cached extractor so the next get() creates a fresh one."""
        self._current = None
        self._current_params = {}

from typing import Optional

from src.interfaces import DEFAULT_PROMPT


class PromptResolver:
    """Resolves the effective prompt from an optional user override."""

    def __init__(self, default_prompt: str = DEFAULT_PROMPT):
        self.default_prompt = default_prompt

    def resolve(self, user_prompt: Optional[str] = None) -> str:
        """Return user_prompt if provided, otherwise the default prompt."""
        return user_prompt or self.default_prompt

import dash
import dash_bootstrap_components as dbc
from dash import Input, Output, State, html

from src.components import build_folder_controls
from src.coordinator import FolderImageSource
from src.discovery import clear_processed_cache


def register_folder_callback(app):
    @app.callback(
        Output("folder-file-list", "children"),
        Output("folder-cache", "data"),
        Output("photo-list-store", "data"),
        Output("selected-tags-store", "data", allow_duplicate=True),
        Output("tag-cloud-data-store", "data", allow_duplicate=True),
        Output("tag-cloud-results", "children", allow_duplicate=True),
        Input("input-folder", "value"),
        Input("btn-rescan", "n_clicks"),
        State("input-batch-size", "value"),
        State("chk-recursive", "value"),
        prevent_initial_call="initial_duplicate",
        running=[
            (Output("btn-rescan", "disabled"), True, False),
            (Output("btn-rescan", "children"), "Scanning…", "Rescan folder"),
        ],
    )
    def update_folder_list(folder, n_clicks, batch_size, recursive):
        if not folder:
            return dbc.Badge("Enter a folder path", color="secondary"), {}, dash.no_update, dash.no_update, dash.no_update, dash.no_update

        if n_clicks:
            clear_processed_cache(folder)

        try:
            limit = int(batch_size) if batch_size else 10
            if limit <= 0:
                limit = None

            source = FolderImageSource(folder, recursive=bool(recursive), exclude_processed=True)
            image_paths = source.list_images(limit=limit)
            total_remaining = source.total_pending()
            total_all = source.total_all()

            cache_data = {
                "folder": folder,
                "recursive": recursive,
                "total_all": total_all,
                "total_remaining": total_remaining,
                "batch_size": batch_size,
            }

            controls = build_folder_controls(image_paths, total_remaining=total_remaining, total_all=total_all, folder=folder)
            list_data = {"paths": image_paths, "index": None}
            if total_all == 0:
                return html.Div([
                    controls,
                    html.Div("No images found in this folder.", className="text-muted mt-2"),
                ]), cache_data, list_data, [], None, html.Div()

            return controls, cache_data, list_data, [], None, html.Div()
        except Exception as e:
            return html.Div(f"Error listing folder: {e}", className="text-danger"), {}, dash.no_update, dash.no_update, dash.no_update, dash.no_update


def register_toggle_callback(app):
    @app.callback(
        Output("folder-files-collapse", "is_open"),
        Input("btn-toggle-files", "n_clicks"),
        State("folder-files-collapse", "is_open"),
        prevent_initial_call=True,
    )
    def toggle_file_list(n_clicks, is_open):
        if n_clicks is None:
            return dash.no_update
        return not is_open

